impl<'a> Lexer<'a> {
    /// Creates a new lexer for the given string.
    pub fn new(input: &'a str) -> Lexer<'a> {
        Self {
            chars: input.chars().peekable(),
        }
    }

    /// Returns the next character if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(char) -> bool) -> Option<char> {
        self.chars.next_if(predicate)
    }

    /// Applies a closure to the next character, returning its result and
    /// consuming the next character if it's Some.
    fn next_if_map<T>(&mut self, map: impl Fn(char) -> Option<T>) -> Option<T> {
        self.chars.next_if_map(map)
    }

    /// Returns true if the next character is the given character, consuming it.
    fn next_is(&mut self, c: char) -> bool {
        self.chars.next_if(|&ch| ch == c).is_some()
    }

    /// Scans the next token, if any.
    fn scan(&mut self) -> Result<Option<Token>> {
        self.scan_ident_or_keyword()
            .or_else(|| self.scan_ident_quoted()?.or_else(|| self.scan_number()))
            .or_else(|| self.scan_string()?.or_else(|| self.scan_symbol()))
    }

    /// Scans the next identifier or keyword, if any. It's converted to
    /// lowercase, by SQL convention.
    fn scan_ident_or_keyword(&mut self) -> Option<Token> {
        let start = self.chars.clone().next()?;
        if !start.is_alphabetic() && start != '_' {
            return None;
        }

        let mut ident = String::new();
        ident.push(start);
        while let Some(c) = self.chars.next_if(|&c| c.is_alphanumeric() || c == '_') {
            ident.push(c);
        }

        let lower = ident.to_lowercase();
        match Keyword::try_from(lower.as_str()) {
            Ok(keyword) => Some(Token::Keyword(keyword)),
            Err(_) => Some(Token::Ident(ident)),
        }
    }

    /// Scans the next quoted identifier, if any. Case is preserved.
    fn scan_ident_quoted(&mut self) -> Result<Option<Token>> {
        let start = self.chars.next_if(|&c| c == '"');
        if start.is_none() {
            return Ok(None);
        }

        let mut ident = String::new();
        loop {
            match self.chars.next() {
                Some('"') => return Ok(Some(Token::Ident(ident))),
                Some(c) => ident.push(c),
                None => return errinput!("unterminated quoted identifier"),
            }
        }
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let mut num = String::new();

        // Optional leading minus (we don't consume it, it's a separate token)
        if self.chars.peek().copied() == Some('-') {
            return None;
        }

        // Integer part
        while let Some(c) = self.chars.next_if(|&c| c.is_ascii_digit()) {
            num.push(c);
        }

        // Decimal point and fractional part
        if self.chars.peek().copied() == Some('.') {
            num.push('.');
            while let Some(c) = self.chars.next_if(|&c| c.is_ascii_digit()) {
                num.push(c);
            }
        }

        // Exponent
        if let Some('e' | 'E') = self.chars.peek() {
            num.push('e');
            if self.chars.next_if(|&c| c == '+' || c == '-') {
                // consume sign
            }
            while let Some(c) = self.chars.next_if(|&c| c.is_ascii_digit()) {
                num.push(c);
            }
        }

        if num.is_empty() || num == "." || num == "-" || num == "-." || num.ends_with('.') {
            None
        } else {
            Some(Token::Number(num))
        }
    }

    /// Scans the next quoted string literal, if any.
    fn scan_string(&mut self) -> Result<Option<Token>> {
        let start = self.chars.next_if(|&c| c == '\'');
        if start.is_none() {
            return Ok(None);
        }

        let mut s = String::new();
        loop {
            match self.chars.next() {
                Some('\'') => {
                    // Check for escaped quote
                    if self.chars.next_if(|&c| c == '\'') {
                        s.push('\'');
                    } else {
                        return Ok(Some(Token::String(s)));
                    }
                }
                Some('\\') => {
                    match self.chars.next() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('\\') => s.push('\\'),
                        Some('\'') => s.push('\''),
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return errinput!("unterminated string escape"),
                    }
                }
                Some(c) => s.push(c),
                None => return errinput!("unterminated string"),
            }
        }
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Option<Token> {
        let c = self.chars.peek()?;
        match c {
            '.' => { self.chars.next(); Some(Token::Period) }
            '=' => { self.chars.next(); Some(Token::Equal) }
            '!' => {
                self.chars.next();
                if self.chars.next_if(|&c| c == '=') {
                    Some(Token::NotEqual)
                } else {
                    Some(Token::Exclamation)
                }
            }
            '<' => {
                self.chars.next();
                match self.chars.peek() {
                    Some('=') => { self.chars.next(); Some(Token::LessThanOrEqual) }
                    Some('>') => { self.chars.next(); Some(Token::LessOrGreaterThan) }
                    _ => Some(Token::LessThan)
                }
            }
            '>' => {
                self.chars.next();
                if self.chars.next_if(|&c| c == '=') {
                    Some(Token::GreaterThanOrEqual)
                } else {
                    Some(Token::GreaterThan)
                }
            }
            '+' => { self.chars.next(); Some(Token::Plus) }
            '-' => { self.chars.next(); Some(Token::Minus) }
            '*' => { self.chars.next(); Some(Token::Asterisk) }
            '/' => { self.chars.next(); Some(Token::Slash) }
            '^' => { self.chars.next(); Some(Token::Caret) }
            '%' => { self.chars.next(); Some(Token::Percent) }
            '?' => { self.chars.next(); Some(Token::Question) }
            ',' => { self.chars.next(); Some(Token::Comma) }
            ';' => { self.chars.next(); Some(Token::Semicolon) }
            '(' => { self.chars.next(); Some(Token::OpenParen) }
            ')' => { self.chars.next(); Some(Token::CloseParen) }
            _ => None,
        }
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while let Some(&c) = self.chars.peek() {
            if c.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }
}

/// Returns true if the entire given string is a single valid identifier.
pub fn is_ident(ident: &str) -> bool {
    let mut chars = ident.chars();
    match chars.next() {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_alphanumeric() || c == '_')
}
